"""The router calldata against two real transactions on the operator's sub-1% pools (Robinhood Chain, Oct 7-8): a crowd buy
(0xa9e8c3ac..., a single-use wallet's first transaction, 0.1103 ETH into the 0.2748% pool of token 0xebe3c698) and a fleet sell
(0xfbbe3ad9..., wallet 0x75442507 at nonce 1448, every token it held into the 0.1786% pool of token 0x177711dc), plus the two
approvals that wallet sent at nonces 1446 and 1447. The engine's bytes must equal theirs.
Plain script: python3 tests/test_ur.py"""
import os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, os.path.join(ROOT, "src"))
import ur

CROWD_BUY = ""
FLEET_SELL = ""
FLEET_APPROVE = "0x095ea7b3000000000000000000000000000000000022d473030f116ddee9f6b43ac78ba3ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff"
FLEET_PERMIT2 = ("0x87517c45000000000000000000000000177711dc9b03ada0ef4dbc2d7479d6fdebd81a660000000000000000000000008876789976decbfcbbbe364623c63652db8c0904"
                 "000000000000000000000000ffffffffffffffffffffffffffffffffffffffff0000000000000000000000000000000000000000000000000000ffffffffffff")
assert len(CROWD_BUY) == len(FLEET_SELL) == 10 + 35 * 64, (len(CROWD_BUY), len(FLEET_SELL))

key_buy = {"c0": "0" * 40, "token": "ebe3c6989e116287667cf49f77b14d41f86ae003", "fee": 2748, "tick_spacing": 200, "hooks": "0" * 40}
got = ur.buy_calldata(key_buy, 110300000000000000, 0x2e1f41bd5d3ea75cdf24c8, 0)
assert got == CROWD_BUY, next((f"word {i}: {got[10 + 64*i: 10 + 64*(i+1)]} vs {CROWD_BUY[10 + 64*i: 10 + 64*(i+1)]}" for i in range(35) if got[10 + 64*i: 10 + 64*(i+1)] != CROWD_BUY[10 + 64*i: 10 + 64*(i+1)]), "length")
assert int(got[2 + 2 * ur.AMOUNT_IN_OFFSET: 2 + 2 * ur.AMOUNT_IN_OFFSET + 64], 16) == 110300000000000000, "AMOUNT_IN_OFFSET"
print("ok the crowd's buy, byte for byte (1120 bytes: V4_SWAP, SWAP_EXACT_IN_SINGLE + SETTLE_ALL + TAKE_ALL, no hook data, deadline 2^256-1)")

key_sell = {"c0": "0" * 40, "token": "177711dc9b03ada0ef4dbc2d7479d6fdebd81a66", "fee": 1786, "tick_spacing": 200, "hooks": "0" * 40}
got = ur.sell_calldata(key_sell, 0x1d4408e8b07b62a94eacd, 0x1a37e50d46ca2e, 0)
assert got == FLEET_SELL, next((f"word {i}: {got[10 + 64*i: 10 + 64*(i+1)]} vs {FLEET_SELL[10 + 64*i: 10 + 64*(i+1)]}" for i in range(35) if got[10 + 64*i: 10 + 64*(i+1)] != FLEET_SELL[10 + 64*i: 10 + 64*(i+1)]), "length")
assert int(got[2 + 2 * ur.AMOUNT_IN_OFFSET: 2 + 2 * ur.AMOUNT_IN_OFFSET + 64], 16) == 0x1d4408e8b07b62a94eacd
print("ok the fleet's sell, byte for byte")

assert ur.approve_permit2_calldata() == FLEET_APPROVE and ur.permit2_approve_calldata(key_sell["token"]) == FLEET_PERMIT2
print("ok the fleet's two approvals (token -> Permit2 unlimited; Permit2 -> router unlimited, never expiring)")

# a deadline, and the uint128 guard
d = ur.buy_calldata(key_buy, 10 ** 15, 1, 1_760_000_000); assert int(d[10 + 64*2: 10 + 64*3], 16) == 1_760_000_000 and len(d) == len(CROWD_BUY)
try:
    ur.sell_calldata(key_sell, 1 << 128, 0); raise SystemExit("a uint128 overflow was accepted")
except ValueError:
    pass
print("ok deadline word, uint128 guard")

# tokens_received: the token's Transfer to the wallet (exact), else the Swap's amount1
PM = "0x8366a39cc670b4001a1121b8f6a443a643e40951"; W = "0x" + "ab" * 20; TOKEN = "0x" + key_sell["token"]; w = ur.word
rec = {"logs": [{"address": PM, "topics": ["0x" + ur.T_SWAP, "0x" + "77" * 32, w(ur.UR)], "data": "0x" + w(-10 ** 15) + w(12345) + w(0) + w(0) + w(0) + w(0)},
                {"address": TOKEN, "topics": ["0x" + ur.T_TRANSFER, w(PM), w(W)], "data": "0x" + w(12340)}]}
assert ur.tokens_received(rec, TOKEN, W) == 12340, "the Transfer to the wallet decides"
rec["logs"].pop(); assert ur.tokens_received(rec, TOKEN, W) == 12345, "the Swap's amount1 when there is no Transfer"
assert ur.tokens_received({"logs": []}, TOKEN, W) == 0
print("ok tokens_received")
